// CSD_RATIONALE_BEGIN
// Root cause of 49.7% plateau: IsCompletePrefix fires on trivially-complete SQL
// after only ~5 constrained tokens, before WHERE/GROUP BY/HAVING conditions are
// generated. Example: "SELECT MIN(cars_data.weight) FROM cars" (6 tokens) closes
// without "WHERE cylinders = 8 AND year = 1974". Evidence: avg 11.79 total tokens
// = ~3 preamble + 1 open + ~5 SQL + 1 close — far too short for full Spider queries.
//
// Fix: add minSQLTokens=8 requirement before IsCompletePrefix closes the span.
// This ensures at least 8 constrained tokens are generated, giving the model room
// to emit WHERE/GROUP BY/HAVING conditions before closure.
//
// Additional changes vs best attempt (41):
//   - Reduce preamble from 5 to 3 steps (frees 2 more steps for SQL content)
//   - Require |currentConstrainedOut| >= 8 before IsCompletePrefix early-close
//   - Cap SQL generation loop at 150 steps (prevent repetition, previously none)
//   - Keep GroupBoostedConstrainedStep(6.0) for schema token grounding
//   - Keep CloseSpanWithinBudget fallback capped at 100 steps
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop runs only while !insideConstrainedOut. On
//   RenderedEndsWith(generated, "<<") we set currentConstrainedOut := [], which
//   satisfies IsValidPrefix([]) by method precondition. On EOS break,
//   insideConstrainedOut stays false, making the implication vacuous.
//
// Phase 2 (OpenConstrainedSpan): Only runs when !insideConstrainedOut. Sets
//   currentConstrainedOut := []; IsValidPrefix([]) by precondition.
//
// Phase 3 (constrained generation loop):
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making implication vacuous and currentConstrainedOut := [].
//   Normal generation branch: GroupBoostedConstrainedStep hard-masks to parser-valid
//   tokens plus EOS; AppendConstrainedToken extends currentConstrainedOut by one
//   parser-valid token, preserving IsValidPrefix by the parser extension contract.
//   EOS+close branch: CloseConstrainedSpan sets insideConstrainedOut := false.
//
// Phase 4: CloseConstrainedSpan branch makes implication vacuous.
//   CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). Invariant preserved each iteration.
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
// Phase 3: IsCompletePrefix branch: steps += 1, CloseConstrainedSpan appends at most 1
//   ">>" token; net ≤1 token per +1 step. Normal generation: steps += 1 (GroupBoosted),
//   sqlSteps += 1, AppendConstrainedToken appends 1 token; net = 1 token per 1 step.
//   EOS+close: steps += 1 (EOS) then steps += 1 (close), generated += 1 (">>"). Net ≤ 2
//   tokens for 2 steps. All paths preserve the invariant.
// Phase 4: CloseSpanWithinBudget postcondition gives |generatedOut| <= |generated| + closeBudget.
//   We set steps := steps + closeBudget, so |generated_out| <= |generatedPrefix| + steps_out.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output SQL: <<query>> where the query is a valid SQL SELECT statement using only the given schema tables and columns. Put your answer between << and >>. No explanation.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var minSQLTokens: nat := 8;
var maxSQLSteps: nat := 150;

// Phase 1: Short preamble (at most 3 steps) to let model emit "SQL: " prefix.
var preambleBudget: nat := 3;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constraint with minimum-length guard.
// Only close early if |currentConstrainedOut| >= minSQLTokens to prevent
// premature closure before WHERE/GROUP BY/HAVING conditions are generated.
var sqlSteps: nat := 0;

while steps < maxSteps && insideConstrainedOut && sqlSteps < maxSQLSteps
  invariant 0 <= steps <= maxSteps
  invariant 0 <= sqlSteps <= maxSQLSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSQLTokens {
    // Close only when we have a meaningful complete SQL (>= 8 constrained tokens).
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      // On EOS, close if already complete (even if short — model chose to stop).
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, attempt clean closure.
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remainingBudget := maxSteps - steps;
    var closeBudget: nat;
    if remainingBudget <= 100 {
      closeBudget := remainingBudget;
    } else {
      closeBudget := 100;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

